package com.noir.player;

import android.content.*;
import android.content.pm.ActivityInfo;
import android.content.res.Configuration;
import android.graphics.*;
import android.os.Looper;
import android.view.*;
import java.io.*;
import java.time.Duration;
import java.util.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk=28,qualifiers="w360dp-h800dp-xxhdpi",shadows=YouTubeScreenTest.RecordingSession.class)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PlayerUiImprovementTest {
 public static class UiPlayback extends PlaybackService {
  boolean running=true;int delta;int offset=62000;
  @Override public boolean playing(){return running;}
  @Override public int duration(){return 242000;}
  @Override public int position(){return offset;}
  @Override public void skip(int amount){delta+=amount;}
  @Override public void toggle(){running=!running;update();}
  @Override void load(android.net.Uri uri,String name){source=uri.toString();title=name;}
 }
 UiPlayback fixture(UiPlayback s){s.hasVideo=true;s.title="Coastline · Sample clip";s.artist="Local video";s.source="content://fixture/clip.mp4";s.artwork=poster();s.queue=new PlaybackQueue(Arrays.asList(new LibraryStore.Track("content://fixture/a","First","video/mp4"),new LibraryStore.Track(s.source,s.title,"video/mp4"),new LibraryStore.Track("content://fixture/c","Last","video/mp4")),s.source,s.title);return s;}
 static Bitmap poster(){Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint(3);p.setShader(new LinearGradient(0,0,960,540,new int[]{0xff16323d,0xff376c7b,0xffd6ac70},null,Shader.TileMode.CLAMP));c.drawRect(0,0,960,540,p);p.setShader(null);p.setColor(0xff172f38);Path hills=new Path();hills.moveTo(0,400);hills.cubicTo(200,200,280,300,440,360);hills.cubicTo(600,230,740,220,960,350);hills.lineTo(960,540);hills.lineTo(0,540);hills.close();c.drawPath(hills,p);p.setColor(0xffffd99c);c.drawCircle(720,120,48,p);return b;}
 static void layout(View v,int w,int h){v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);}
 static void save(View v,int w,int h,String file)throws Exception{layout(v,w,h);Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File dir=new File("build/player-screenshots");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,file))){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
 @Test public void compactSettingsKeepThemeAndStyleChangesInOneSheet()throws Exception{try(var c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();a.settings();PlayerSettingsSheet sheet=a.settingsSheet;assertTrue(sheet.isShowing());sheet.setTheme(6);assertEquals(6,a.prefs.getInt("theme",-1));assertTrue(sheet.swatches.get(6).isSelected());sheet.matrix.performClick();assertTrue(a.prefs.getBoolean("dots",false));assertEquals(View.VISIBLE,a.view.getVisibility());sheet.normal.performClick();assertEquals(View.VISIBLE,a.normalPlayer.getVisibility());sheet.filled.setChecked(false);assertFalse(a.prefs.getBoolean("filled",true));sheet.lock.setChecked(true);assertTrue(a.prefs.getBoolean("lock",false));assertTrue(sheet.isShowing());View decor=sheet.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1800,View.MeasureSpec.AT_MOST));int height=decor.getMeasuredHeight();assertTrue(height<1800);save(decor,1080,height,"settings-v1.11.png");sheet.dismiss();}}
 @Test public void normalHomeUsesCashewControlsAndFullWidthInlineVideo()throws Exception{var service=Robolectric.buildService(UiPlayback.class).create();try(var c=Robolectric.buildActivity(MainActivity.class).setup()){UiPlayback s=fixture(service.get());MainActivity a=c.get();a.prefs.edit().putBoolean("dots",false).putBoolean("video_mode",false).apply();a.refreshPlayerStyle();NativePlayerView v=a.normalPlayer;layout(v,1080,2200);assertTrue(v.previousTrack instanceof CashewButton);assertTrue(v.nextTrack instanceof CashewButton);assertTrue(v.previousTrack.getHeight()>=v.dp(48));int audioHeight=v.media.getHeight();save(v,1080,2200,"native-audio-v1.11.png");v.watch.performClick();layout(v,1080,2200);assertTrue(v.watch.isSelected());assertEquals(1080,v.media.getWidth());assertEquals(View.GONE,v.audioControls.getVisibility());assertTrue(v.media.getHeight()>audioHeight+v.dp(160));assertFalse(s.audioOnly);assertEquals(62000,s.position());save(v,1080,2200,"home-video-v1.11.png");v.media.fit.performClick();save(v,1080,2200,"home-video-fill-v1.11.png");assertTrue(v.media.texture.getWidth()>=v.media.getWidth());assertTrue(v.media.texture.getHeight()>=v.media.getHeight());assertEquals(62000,s.position());v.media.fit.performClick();v.audioMode.performClick();assertTrue(s.audioOnly);assertEquals(View.VISIBLE,v.audioControls.getVisibility());assertEquals(62000,s.position());}finally{service.destroy();}}
 @Test public void overlayControlsSwitchModeSeekAndRotateWithoutRestartingPlayback()throws Exception{var service=Robolectric.buildService(UiPlayback.class).create();fixture(service.get());try(var c=Robolectric.buildActivity(VideoActivity.class).setup()){VideoActivity a=c.get();VideoPane p=a.pane;layout(p,1080,2200);assertTrue(p.videoRequested);assertEquals("Pause",p.play.getContentDescription());assertTrue(p.rewind.getHeight()>=p.dp(48));int[] xy=new int[2];p.play.getLocationOnScreen(xy);assertTrue(Math.abs(xy[1]+p.play.getHeight()/2-1100)<p.dp(40));p.rewind.performClick();assertEquals(-10000,service.get().delta);p.forward.performClick();assertEquals(0,service.get().delta);p.mode.performClick();assertTrue(service.get().audioOnly);assertFalse(p.videoRequested);p.mode.performClick();assertFalse(service.get().audioOnly);assertTrue(p.videoRequested);p.rotate.performClick();assertEquals(ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE,a.getRequestedOrientation());save(p,1080,2200,"video-portrait-v1.11.png");RuntimeEnvironment.setQualifiers("w800dp-h360dp-land-xxhdpi");a.onConfigurationChanged(new Configuration(a.getResources().getConfiguration()));save(p,2400,1080,"video-landscape-v1.11.png");assertTrue(p.play.getWidth()<=p.dp(80));assertTrue(p.previous.getWidth()<=p.dp(72));p.rotate.performClick();assertEquals(ActivityInfo.SCREEN_ORIENTATION_SENSOR_PORTRAIT,a.getRequestedOrientation());assertEquals(62000,service.get().position());}finally{service.destroy();}}
 @Test public void overlayHidesOnPlaybackAndTapRestoresIt(){var service=Robolectric.buildService(UiPlayback.class).create();fixture(service.get());try(var c=Robolectric.buildActivity(VideoActivity.class).setup()){VideoPane p=c.get().pane;layout(p,1080,2200);p.showControls();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(3600));assertFalse(p.controlsVisible);MotionEvent down=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,540,500,0),up=MotionEvent.obtain(0,10,MotionEvent.ACTION_UP,540,500,0);try{p.dispatchTouchEvent(down);p.dispatchTouchEvent(up);}finally{down.recycle();up.recycle();}assertTrue(p.controlsVisible);p.play.performClick();assertFalse(service.get().running);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(4));assertTrue(p.controlsVisible);c.pause();assertTrue(service.get().audioOnly);}finally{service.destroy();}}
 // Surface validity is stubbed: this test checks ownership, not hardware decoding.
 @Test public void surfaceOwnershipProtectsNewScreenAndLockLeavesAudioPlaying(){var service=Robolectric.buildService(UiPlayback.class).create();UiPlayback s=fixture(service.get());SurfaceTexture texture=new SurfaceTexture(0);Surface surface=new Surface(texture){@Override public boolean isValid(){return true;}};VideoPane home=new VideoPane(RuntimeEnvironment.getApplication(),false),full=new VideoPane(RuntimeEnvironment.getApplication(),true);try{s.attachVideoSurface(home.owner,null);assertFalse(s.hasVideoSurface());s.setAudioOnly(false);s.attachVideoSurface(home.owner,surface);assertTrue(s.isVideoSurfaceOwner(home.owner));s.attachVideoSurface(full.owner,surface);home.setHostActive(false);assertFalse(s.releaseVideoSurface(home.owner));assertTrue(s.isVideoSurfaceOwner(full.owner));assertFalse(s.audioOnly);full.setHostActive(false);assertFalse(s.hasVideoSurface());assertTrue(s.audioOnly);assertTrue(s.running);assertEquals(62000,s.position());}finally{surface.release();texture.release();service.destroy();}}
 @Test public void swipeRightFromThumbnailOpensNativeVideo(){var service=Robolectric.buildService(UiPlayback.class).create();fixture(service.get());try(var c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();a.normalPlayer.render();VideoPane p=a.normalPlayer.media;layout(p,1080,900);MotionEvent down=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,100,300,0),up=MotionEvent.obtain(0,80,MotionEvent.ACTION_UP,400,310,0);try{p.dispatchTouchEvent(down);p.dispatchTouchEvent(up);}finally{down.recycle();up.recycle();}Intent opened=Shadows.shadowOf(a).getNextStartedActivity();assertNotNull(opened);assertEquals(VideoActivity.class.getName(),opened.getComponent().getClassName());}finally{service.destroy();}}
}
